selector_to_html = {"a[href=\"../design_inputs/DesignContext.html#pyskyfire.regen.design_inputs.DesignContext\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.design_inputs.DesignContext\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.design_inputs.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DesignContext</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">providers</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">Mapping</span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><span class=\"pre\">Any</span><span class=\"p\"><span class=\"pre\">]</span></span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">Mapping</span></code></p><p>Lazily evaluated bundle of design-input quantities at one station.</p><p>Providers are either plain values or zero-argument callables.  A callable\nis invoked at most once, the first time its name is requested, so building\na context for a station that only needs <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> costs nothing.</p></dd>", "a[href=\"#pyskyfire.regen.cross_section.SectionProfiles.__setstate__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.SectionProfiles.__setstate__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__setstate__</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">state</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.cross_section.SectionProfiles.__post_init__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.SectionProfiles.__post_init__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__post_init__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.regen.cross_section.SectionProfiles\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.SectionProfiles\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.cross_section.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SectionProfiles</span></span></dt><dd><p>All geometry profiles along the cooling-channel centerline.</p><p>Each required array must have consistent length <code class=\"docutils literal notranslate\"><span class=\"pre\">N</span></code> (number of stations).</p></dd>", "a[href=\"#pyskyfire-regen-cross-section-sectionprofiles\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.cross_section.SectionProfiles<a class=\"headerlink\" href=\"#pyskyfire-regen-cross-section-sectionprofiles\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.regen.cross_section.SectionProfiles.cached\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.SectionProfiles.cached\">\n<span class=\"sig-name descname\"><span class=\"pre\">cached</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">key</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">compute</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return <code class=\"docutils literal notranslate\"><span class=\"pre\">compute()</span></code> for <code class=\"docutils literal notranslate\"><span class=\"pre\">key</span></code>, evaluating it once per profile.</p><p>A profile is immutable, so anything derived from one stays valid for as\nlong as it lives. The solver depends on that: it holds a station fixed\nwhile it iterates that station\u2019s temperatures, so it asks the same\none-station profile for the same section geometry many times over, and\nboth the boundary integral and the design-input evaluation behind it\nare far too expensive to repeat.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">key</span></code> identifies the computation, and must include whatever object is\ndoing it, since one profile can be measured by more than one section.</p></dd>", "a[href=\"../design_inputs/DesignInputError.html#pyskyfire.regen.design_inputs.DesignInputError\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.design_inputs.DesignInputError\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">exception</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.design_inputs.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DesignInputError</span></span></dt><dd><p>Bases: <a class=\"reference external\" href=\"https://docs.python.org/3/builtins/exceptions.html#ValueError\" title=\"(in Python v3.15)\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">ValueError</span></code></a></p><p>Raised when a design-input function cannot be dispatched or evaluated.</p></dd>", "a[href=\"#pyskyfire.regen.cross_section.SectionProfiles.from_dimensions\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.SectionProfiles.from_dimensions\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_dimensions</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wall_thickness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">floor_width</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roof_width</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">radius</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">angle</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Build local section profiles without a chamber or placed path.</p><p>Supply both internal endpoint widths, or a finite radius and full\noccupied sector angle (radians). With widths, radius only controls\nsquared-arc curvature; omit it for straight ends. Dimensions broadcast\nover stations. <code class=\"docutils literal notranslate\"><span class=\"pre\">stations</span></code> is the local path coordinate in metres,\nexposed as <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> to design-input callables; it is not a placement.</p></dd>", "a[href=\"#pyskyfire.regen.cross_section.SectionProfiles.design_contexts\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.SectionProfiles.design_contexts\">\n<span class=\"sig-name descname\"><span class=\"pre\">design_contexts</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#list\" title=\"(in Python v3.15)\"><span class=\"pre\">list</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference internal\" href=\"../design_inputs/DesignContext.html#pyskyfire.regen.design_inputs.DesignContext\" title=\"pyskyfire.regen.design_inputs.DesignContext\"><span class=\"pre\">DesignContext</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span></span></dt><dd><p>Return one <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">DesignContext</span></code> per station.</p><p>The contexts expose tier A, B and C quantities, so they are what\nsection-level design inputs such as <code class=\"docutils literal notranslate\"><span class=\"pre\">sidewall_half_thickness</span></code> are evaluated\nagainst.</p></dd>", "a[href=\"#pyskyfire.regen.cross_section.SectionProfiles.__getstate__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.cross_section.SectionProfiles.__getstate__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__getstate__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Serialise the fields only; the derived memo is rebuilt on demand.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
